const flip = Math.random() < 0.5;
this.state.correct_side = flip ? 'left' : 'right';
this.state.left_img  = flip ? this.parameters.correct_img : this.parameters.distractor_img;
this.state.right_img = flip ? this.parameters.distractor_img : this.parameters.correct_img;

const side = this.state.response;
this.data.correct_side = this.state.correct_side;
this.data.chosen_side  = side;
this.data.chosen_img   = side === 'left' ? this.state.left_img : this.state.right_img;
this.data.correct      = side === this.state.correct_side ? 1 : 0;

const sfx = { de: '', en: '_EN', fr: '_FR', it: '_IT' }[this.options.datastore.get('language') || 'de'] ?? '';
this.state.cj_unsicher = 'CJ_unsicher' + sfx + '.png';
this.state.cj_mittel   = 'CJ_mittel'   + sfx + '.png';
this.state.cj_sicher   = 'CJ_sicher'   + sfx + '.png';

